let nextId = 1;
const todos = new Map<number, { id: number; text: string; completed: boolean }>();

function addTodo(text: string): void {
    const todo: { id: number; text: string; completed: boolean } = { id: nextId++, text, completed: false };
    todos.set(todo.id, todo);
}

function getTodo(id: number): { id: number; text: string; completed: boolean } | undefined {
    return todos.get(id);
}

function toggleTodo(id: number): void {
    const todo = todos.get(id);
    if (todo) {
        todo.completed = !todo.completed;
    }
}

function deleteTodo(id: number): void {
    todos.delete(id);
}

function listTodos(): { id: number; text: string; completed: boolean }[] {
    return Array.from(todos.values());
}

function listCompleted(): { id: number; text: string; completed: boolean }[] {
    return Array.from(todos.values()).filter(todo => todo.completed);
}

function listPending(): { id: number; text: string; completed: boolean }[] {
    return Array.from(todos.values()).filter(todo => !todo.completed);
}

function clearCompleted(): void {
    const todosToKeep = new Map<number, { id: number; text: string; completed: boolean }>();
    for (const [id, todo] of todos.entries()) {
        if (!todo.completed) {
            todosToKeep.set(id, todo);
        }
    }
    todos.clear();
    todos.forEach((value, key) => todosToKeep.set(key, value));
}

export function createTodoApp() {
    return { addTodo, getTodo, toggleTodo, deleteTodo, listTodos, listCompleted, listPending, clearCompleted };
}
