let nextId = 1;
const todoStorage: Record<number, Todo> = {};

export function createTodoApp(): TodoApp {
  let idCounter = nextId;

  const addTodo = (text: string): Todo => {
    const newTodo: Todo = { id: idCounter++, text, completed: false };
    todoStorage[newTodo.id] = newTodo;
    return newTodo;
  };

  const getTodo = (id: number): Todo | undefined => todoStorage[id];

  const toggleTodo = (id: number): void => {
    if (todoStorage[id]) {
      todoStorage[id].completed = !todoStorage[id].completed;
    }
  };

  const deleteTodo = (id: number): boolean => {
    if (todoStorage[id]) {
      delete todoStorage[id];
      return true;
    }
    return false;
  };

  const listTodos = (): Todo[] => Object.values(todoStorage);

  const listCompleted = (): Todo[] => Object.values(todoStorage).filter(todo => todo.completed);

  const listPending = (): Todo[] => Object.values(todoStorage).filter(todo => !todo.completed);

  const clearCompleted = (): void => {
    for (const id of Object.keys(todoStorage)) {
      if (todoStorage[id] && todoStorage[id].completed) {
        delete todoStorage[id];
      }
    }
  };

  return { addTodo, getTodo, toggleTodo, deleteTodo, listTodos, listCompleted, listPending, clearCompleted };
}
