  function listPending(): Todo[] {
    return todos.filter(todo => !todo.completed);
  }

  function clearCompleted(): void {
    todos = todos.filter(todo => !todo.completed);
  }

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted
  };
}

export { createTodoApp };
