export function createTodoApp(): TodoApp {
    const privateTodos = new Map<number, Todo>();
    let nextId = 1;

    function addTodo(text: string): Todo {
        const newTodo: Todo = { id: nextId, text, completed: false };
        privateTodos.set(nextId, newTodo);
        nextId++;
        return newTodo;
    }

    function getTodo(id: number): Todo | undefined {
        return privateTodos.get(id);
    }

    function toggleTodo(id: number): void {
        const todo = privateTodos.get(id);
        if (todo) {
            todo.completed = !todo.completed;
        }
    }

    function deleteTodo(id: number): boolean {
        return privateTodos.delete(id);
    }

    function listTodos(): Todo[] {
        return Array.from(privateTodos.values());
    }

    function listCompleted(): Todo[] {
        return listTodos().filter(todo => todo.completed);
    }

    function listPending(): Todo[] {
        return listTodos().filter(todo => !todo.completed);
    }

    function clearCompleted(): void {
        const entries = Array.from(privateTodos.entries());
        for (const [id, todo] of entries) {
            if (todo.completed) {
                privateTodos.delete(id);
            }
        }
    }

    return {
        addTodo,
        getTodo,
        toggleTodo,
        deleteTodo,
        listTodos,
        listCompleted,
        listPending,
        clearCompleted,
    };
}
