  const clearCompleted = () => {
    todos = todos.filter(todo => !todo.completed);
    const completedIds = todos.filter(todo => todo.completed).map(todo => todo.id);
    deletedIds = deletedIds.filter(id => !completedIds.includes(id));
  };

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
