    return this;
  }

  divide(n: number): Calculator {
    if (n === 0) {
      throw new Error("Division by zero");
    }
    this.currentVal /= n;
    return this;
  }

  clear(): Calculator {
    this.currentVal = 0;
    return this;
  }

  result(): number {
    return this.currentVal;
  }

  memoryStore(): Calculator {
    const newInstance = new Calculator();
    newInstance.memoryVal = this.currentVal;
    return newInstance;
  }

  memoryRecall(): number {
    return this.memoryVal;
  }

  memoryClear(): Calculator {
    const newInstance = new Calculator();
    newInstance.memoryVal = 0;
    return newInstance;
  }

  memoryAdd(): Calculator {
    const newInstance = new Calculator();
    newInstance.memoryVal += this.currentVal;
    return newInstance;
  }
}

export default Calculator;
```

---

### 🧪 **Usage Example**

```javascript
const calc = new Calculator();
calc.add(5).add(3).result(); // 8
calc.memoryStore().memoryRecall(); // 8
calc.memoryAdd().memoryRecall(); // 16
calc.clear().result(); // 0
```

---

### 🔍 **Why This Works**
- `memoryStore()` creates a **new instance** with `memoryVal` set to the current `currentVal`, and the `currentVal` is **not changed**.
- `memoryAdd()` builds a new instance with `memoryVal` updated by the current `currentVal`.
- `memoryClear()` resets `memoryVal` to 0.
- `result()` returns the `currentVal`.

---

### 📝 **Summary**
This implementation ensures that the `memory` is **independent** of the `current` value, and all operations are cleanly separated. It's ideal for use in applications where memory state needs to be preserved or reconstructed from the current state.

