        this.currentValue = 0;
        return this;
    }

    result(): number {
        return this.currentValue;
    }

    memoryStore(value: number): Calculator {
        if (value !== undefined) this.memoryValue = value;
        return this;
    }

    memoryAdd(value?: number): Calculator {
        if (value === undefined) this.memoryValue += this.currentValue;
        else this.memoryValue += value;
        return this;
    }

    memoryClear(): Calculator {
        this.memoryValue = 0;
        return this;
    }

    memoryRecall(): [number, number] {
        const value = this.memoryValue;
        this.memoryValue = 0;
        return [value, this.currentValue];
    }
