class Todo {
  private static _id = 1;

  constructor(public id: number, public text: string, public completed: boolean) {
    if (completed && this.id > 0) {
      throw new Error('Cannot set todo as completed');
    }
    Todo._id++;
  }

  addTodo() {
    return { id: this.id++, text: '', completed: false };
  }

  getTodo(id: number): { id: number; text: string; completed: boolean } | null {
    if (this.id === id) {
      const newId = this.id;
      this.id++;
      if (newId > 0 && !this.completed) {
        return this.addTodo();
      }
      return { id, text: this.text, completed: this.completed };
    }
    return null;
  }

  toggleTodo() {}

  deleteTodo() {}

  listTodos(): { id: number; text: string; completed: boolean }[] {
    const todos = [];
    for (let i = 1; i <= Todo._id; i++) {
      if (!i.completed) {
        todos.push({ id: i, text: '', completed: false });
      }
    }
    return todos;
  }

  listCompleted(): { id: number; text: string; completed: boolean }[] {
    const completedTodos = [];
    for (let i = 1; i <= Todo._id; i++) {
      if (i.completed) {
        completedTodos.push({ id: i, text: '', completed: true });
      }
    }
    return completedTodos;
  }

  listPending(): { id: number; text: string; completed: boolean }[] {
    const pendingTodos = [];
    for (let i = 1; i <= Todo._id; i++) {
      if (!i.completed) {
        pendingTodos.push({ id: i, text: '', completed: false });
      }
    }
    return pendingTodos;
  }

  clearCompleted(): void {}
}

