interface Calculator {
  add(n: number): Calculator;
  subtract(n: number): Calculator;
  multiply(n: number): Calculator;
  divide(n: number): Calculator;
  clear(): Calculator;
  result(): number;
  memoryStore(): Calculator;
  memoryRecall(): number;
  memoryClear(): Calculator;
  memoryAdd(): Calculator;
}

class CalcImpl implements Calculator {
  private cur = 0;
  private mem = 0;

  add(n: number): this {
    this.cur += n;
    return this;
  }

  subtract(n: number): this {
    this.cur -= n;
    return this;
  }

  multiply(n: number): this {
    this.cur *= n;
    return this;
  }

  divide(n: number): this {
    if (n !== 0) {
      this.cur /= n;
    } else {
      // Infinity for division by zero
      this.cur = Infinity;
    }
    return this;
  }

  clear(): this {
    this.cur = 0;
    return this;
  }

  result(): number {
    return this.cur;
  }

  memoryStore(): this {
    this.mem = this.cur;
    return this;
  }

  memoryRecall(): number {
    return this.mem;
  }

  memoryClear(): this {
    this.mem = 0;
    return this;
  }

  memoryAdd(): this {
    this.mem += this.cur;
    return this;
  }
}

export function createCalculator(): Calculator {
  return new CalcImpl();
}
