export function createTodoApp() {
  let nextId = 1;
  let todos: { id: number; text: string; completed: boolean }[] = [];

  const addTodo = (text: string): void => {
    if (!text) return;
    todos.push({ id: nextId, text, completed: false });
    nextId++;
  };

  const getTodo = (id: number): { id: number; text: string; completed: boolean } | undefined => {
    return todos.find(todo => todo.id === id);
  };

  const toggleTodo = (id: number): void => {
    const todo = todos.find(t => t.id === id);
    if (todo) {
      todo.completed = !todo.completed;
    }
  };

  const deleteTodo = (id: number): void => {
    const index = todos.findIndex(t => t.id === id);
    if (index !== -1) {
      todos.splice(index, 1);
    }
  };

  const listTodos = (): { id: number; text: string; completed: boolean }[] => {
    return todos.map(t => ({ ...t }));
  };

  const listCompleted = (): { id: number; text: string; completed: boolean }[] => {
    return todos.filter(t => t.completed).map(t => ({ ...t }));
  };

  const listPending = (): { id: number; text: string; completed: boolean }[] => {
    return todos.filter(t => !t.completed).map(t => ({ ...t }));
  };

  const clearCompleted = (): void => {
    for (let i = todos.length - 1; i >= 0; i--) {
      if (todos[i].completed) {
        todos.splice(i, 1);
      }
    }
  };

  return { addTodo, getTodo, toggleTodo, deleteTodo, listTodos, listCompleted, listPending, clearCompleted };
}
