export function createCalculator() {
    let currentValue = 0;
    let memoryValue = 0;

    const add = (num: number): Calculator => {
        currentValue += num;
        return calculatorInstance;
    };

    const subtract = (num: number): Calculator => {
        currentValue -= num;
        return calculatorInstance;
    };

    const multiply = (num: number): Calculator => {
        currentValue *= num;
        return calculatorInstance;
    };

    const divide = (num: number): Calculator => {
        if (num === 0) {
            throw new Error('Cannot divide by zero');
        }
        currentValue /= num;
        return calculatorInstance;
    };

    const clear = (): Calculator => {
        currentValue = 0;
        return calculatorInstance;
    };

    const result = (): number => {
        return currentValue;
    };

    const memoryStore = (): Calculator => {
        memoryValue = currentValue;
        return calculatorInstance;
    };

    const memoryAdd = (): Calculator => {
        memoryValue += currentValue;
        return calculatorInstance;
    };

    const memoryClear = (): Calculator => {
        memoryValue = 0;
        return calculatorInstance;
    };

    const memoryRecall = () => {
        return memoryValue;
    };

    const calculatorInstance: Calculator = {
        add,
        subtract,
        multiply,
        divide,
        clear,
        result,
        memoryStore,
        memoryAdd,
        memoryClear,
        memoryRecall
    };

    return { ...calculatorInstance };
}

