export function createCalculator(): Calculator {
  let currentValue = 0;
  let memoryValue = 0;

  const calculator: Calculator = {
    add(n: number): Calculator {
      currentValue += n;
      return this;
    },

    subtract(n: number): Calculator {
      currentValue -= n;
      return this;
    },

    multiply(n: number): Calculator {
      if (currentValue === 0) {
        currentValue = n;
      } else {
        currentValue *= n;
      }
      return this;
    },

    divide(n: number): Calculator {
      if (n !== 0) {
        currentValue /= n;
      }
      return this;
    },

    clear(): Calculator {
      currentValue = 0;
      return this;
    },

    result(): number {
      return currentValue;
    },

    memoryStore(): Calculator {
      memoryValue = currentValue;
      return this;
    },

    memoryRecall(): number {
      return memoryValue;
    },

    memoryClear(): Calculator {
      memoryValue = 0;
      return this;
    },

    memoryAdd(): Calculator {
      if (memoryValue !== 0) {
        currentValue += memoryValue;
        memoryValue = currentValue;
      }
      return this;
    },

  };

  return calculator;
