    nextId++;
    return newTodo;
  }

  function getTodo(id: number): Todo | undefined {
    return todos[id];
  }

  function toggleTodo(id: number) {
    const todo = getTodo(id);
    if (todo !== undefined) {
      todo.completed = !todo.completed;
    }
  }

  function deleteTodo(id: number) {
    delete todos[id];
  }

  function listTodos(): Todo[] {
    return Object.values(todos).sort((a, b) => a.id - b.id);
  }

  function listCompleted(): Todo[] {
    return Object.values(todos).filter(todo => todo.completed).sort((a, b) => a.id - b.id);
  }

  function listPending(): Todo[] {
    return Object.values(todos).filter(todo => !todo.completed).sort((a, b) => a.id - b.id);
  }

  function clearCompleted() {
    for (const id of Array.from(Object.keys(todos)).map(key => parseInt(key))) {
      if (getTodo(id)?.completed === true) {
        deleteTodo(id);
      }
    }
  }

  return { addTodo, getTodo, toggleTodo, deleteTodo, listTodos, listCompleted, listPending, clearCompleted };
}
