const todoList = new Map<number, Todo>();

let nextId = 1;

export function createTodoApp(): TodoApp {
  const addTodo = (text: string): Todo => {
    todoList.set(nextId, { id: nextId, text, completed: false });
    return todoList.get(nextId)!;
  };

  const getTodo = (id: number): Todo | undefined => todoList.get(id);

  const toggleTodo = (id: number): void => {
    const currentTodo = todoList.get(id);
    if (currentTodo) {
      currentTodo.completed = !currentTodo.completed;
      // Update the Map with the toggled todo
      todoList.set(id, { ...currentTodo });
    }
  };

  const deleteTodo = (id: number): boolean => {
    return todoList.delete(id);
  };

  const listTodos = (): Todo[] =>
    Array.from(todoList.values()).sort((a, b) => a.id - b.id);

  const listCompleted = (): Todo[] =>
    Array.from(todoList.values())
      .filter(todo => todo.completed)
      .sort((a, b) => a.id - b.id);

  const listPending = (): Todo[] =>
    Array.from(todoList.values())
      .filter(todo => !todo.completed)
      .sort((a, b) => a.id - b.id);

  const clearCompleted = (): void => {
    // Filter completed todos and delete them
    todoList.forEach((value, key) => {
      if (value.completed) todoList.delete(key);
    });
  };

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted
  };
