```typescript
export interface Todo {
  id: number;
  text: string;
  completed: boolean;
}

export interface TodoApp {
  addTodo(text: string): Todo;
  getTodo(id: number): Todo | undefined;
  toggleTodo(id: number): void;
  deleteTodo(id: number): boolean;
  listTodos(): Todo[];
  listCompleted(): Todo[];
  listPending(): Todo[];
  clearCompleted(): void;
}

export function createTodoApp(): TodoApp {
  let todos: Todo[] = [];
  let nextId = 1;

  return {
    addTodo(text: string): Todo {
      const id = nextId++;
      const todo: Todo = { id, text, completed: false };
      todos.push(todo);
      return todo;
    },

    getTodo(id: number): Todo | undefined {
      return todos.find(todo => todo.id === id);
    },

    toggleTodo(id: number): void {
      const todo = todos.find(todo => todo.id === id);
      if (todo) {
        todo.completed = !todo.completed;
      }
    },

    deleteTodo(id: number): boolean {
      const index = todos.findIndex(todo => todo.id === id);
      if (index !== -1) {
        todos.splice(index, 1);
        return true;
      }
      return false;
    },

    listTodos(): Todo[] {
      return [...todos];
    },

    listCompleted(): Todo[] {
      return todos.filter(todo => todo.completed);
    },

    listPending(): Todo[] {
      return todos.filter(todo => !todo.completed);
    },

    clearCompleted(): void {
      todos = todos.filter(todo => !todo.completed);
    }
  };
}
```

---

### 🧠 Key Design Decisions

1. **State Encapsulation**:
   - `todos` array and `nextId` are declared inside `createTodoApp`, making them private state that's only accessible to the object's methods.

2. **Immutability & Cloning**:
   - Methods like `listTodos`, `listCompleted`, and `listPending` return **copies** of the array to avoid accidental mutation by outside code.
   - `clearCompleted` filters and reassigns the `todos` variable to ensure the state is updated and future operations reflect the changes.

3. **ID Assignment**:
   - The `nextId` variable is incremented every time a new todo is created to ensure **ID uniqueness**.
   - Even if some todos are deleted, their IDs are **not reused** because `nextId` is not reset.

