function createCalculator() {
  let value = 0;
  let memory = 0;

  return {
    /**
     * Adds a value to the calculator's current value.
     * 
     * @param num The value to add.
     * @returns The calculator instance for method chaining.
     */
    add(num: number) {
      value += num;
      return this;
    },

    /**
     * Subtracts a value from the calculator's current value.
     * 
     * @param num The value to subtract.
     * @returns The calculator instance for method chaining.
     */
    subtract(num: number) {
      value -= num;
      return this;
    },

    /**
     * Multiplies the calculator's current value by a number.
     * 
     * @param num The multiplier.
     * @returns The calculator instance for method chaining.
     */
    multiply(num: number) {
      value *= num;
      return this;
    },

    /**
     * Divides the calculator's current value by a number.
     * 
     * @param num The divisor.
     * @returns The calculator instance for method chaining.
     */
    divide(num: number) {
      value /= num;
      return this;
    },

    /**
     * Clears the calculator's current value to 0.
     * This does not affect the memory value.
     * 
     * @returns The calculator instance for method chaining.
     */
    clear() {
      value = 0;
      return this;
    },

    /**
     * Returns the current result of the calculator.
     * 
     * @returns The current value as a number.
     */
    result(): number {
      return value;
    },

    /**
     * Stores the current value in memory.
     * Copies value to memory without modifying value.
     * 
     * @returns The calculator instance for method chaining.
     */
    memoryStore() {
      memory = value;
      return this;
    },

    /**
     * Adds the current value to the stored memory value.
     * Does not take any arguments.
     * 
     * @returns The calculator instance for method chaining.
     */
    memoryAdd() {
      memory += value;
      return this;
    },

    /**
     * Clears the memory value to 0.
     * This does not affect the current value.
     * 
     * @returns The calculator instance for method chaining.
     */
    memoryClear() {
      memory = 0;
      return this;
    },

    /**
     * Retrieves the current memory value.
     * Does not change the calculator's current value.
     * 
     * @returns The stored memory value as a number.
     */
    memoryRecall(): number {
      return memory;
    }
  };
}

export { createCalculator };
