/** Next available todo ID (auto-incremented). IDs are never reused after deletion. */
let nextId = 1;

/** In-memory storage for todos. */
let todos: { id: number; text: string; completed: boolean }[] = [];

/**
 * Factory function creating a todo app interface.
 * @returns Object containing todo management methods.
 */
function createTodoApp() {
  return {
    /** Adds a new todo with auto-incremented ID. */
    addTodo(text: string): { id: number; text: string; completed: boolean } {
      const todo = { id: nextId++, text, completed: false };
      todos.push(todo);
      return todo;
    },

    /** Retrieves a todo by its ID. */
    getTodo(id: number): { id: number; text: string; completed: boolean } | undefined {
      return todos.find(todo => todo.id === id);
    },

    /** Toggles the completion status of a todo. */
    toggleTodo(id: number): { id: number; text: string; completed: boolean } | undefined {
      const todo = todos.find(todo => todo.id === id);
      if (todo !== undefined) {
        todo.completed = !todo.completed;
      }
      return todo;
    },

    /** Deletes a todo by its ID. */
    deleteTodo(id: number): void {
      const index = todos.findIndex(todo => todo.id === id);
      if (index !== -1) {
        todos.splice(index, 1);
      }
    },

    /** Lists all todos. */
    listTodos(): { id: number; text: string; completed: boolean }[] {
      return [...todos];
    },

    /** Lists all completed todos. */
    listCompleted(): { id: number; text: string; completed: boolean }[] {
      return todos.filter(todo => todo.completed);
    },

    /** Lists all pending (uncompleted) todos. */
    listPending(): { id: number; text: string; completed: boolean }[] {
      return todos.filter(todo => !todo.completed);
    },

    /** Removes all completed todos. */
    clearCompleted(): void {
      todos = todos.filter(todo => !todo.completed);
    }
  };
}

export { createTodoApp };
