export function createTodoApp(): TodoApp {
  const todos: Todo[] = [];
  let nextId = 1;
  const deletedIds: Set<number> = new Set();

  return {
    addTodo(text) {
      const id = deletedIds.size > 0 
        ? [...deletedIds].sort((a, b) => a - b)[0] 
        : nextId++;

      if (deletedIds.has(id)) {
        deletedIds.delete(id);
      }

      const todo = { id, text, completed: false };
      todos.push(todo);
      return todo;
    },

    getTodo(id) {
      return todos.find(todo => todo.id === id);
    },

    toggleTodo(id) {
      const todo = this.getTodo(id);
      if (todo) {
        todo.completed = !todo.completed;
      }
    },

    deleteTodo(id) {
      const index = todos.findIndex(todo => todo.id === id);
      if (index !== -1) {
        todos.splice(index, 1);
        deletedIds.add(id);
        return true;
      }
      return false;
    },

    listTodos() {
      return [...todos];
    },

    listCompleted() {
      return todos.filter(todo => todo.completed);
    },

    listPending() {
      return todos.filter(todo => !todo.completed);
    },

    clearCompleted() {
      const remainingTodos = todos.filter(todo => !todo.completed);
      todos.length = 0;
      todos.push(...remainingTodos);

