export function createTodoApp(): TodoApp {
  return {
    addTodo(text: string): Todo {
      const newTodo: Todo = { id: currentId++, text, completed: false };
      todos[newTodo.id] = newTodo;
      return newTodo;
    },

    getTodo(id: number): Todo | null {
      return todos.hasOwnProperty(id) ? todos[id] : null;
    },

    toggleTodo(id: number): boolean {
      if (!todos.hasOwnProperty(id)) return false;
      todos[id].completed = !todos[id].completed;
      return true;
    },

    deleteTodo(id: number): boolean {
      if (!todos.hasOwnProperty(id)) return false;

      delete todos[id];
      return true;
    },

    listTodos(): Todo[] {
      return Object.values(todos);
    },

    listCompleted(): Todo[] {
      return Object.values(todos).filter(todo => todo.completed);
    },

    listPending(): Todo[] {
      return Object.values(todos).filter(todo => !todo.completed);
    },

    clearCompleted(): boolean {
      for (const id in todos) {
          if ((todos as Record<string, Todo>)[id].completed) {
            delete (todos as Record<string, Todo>)[id];
          }
        }
      return Boolean(Object.keys(todos).length !== Object.values(todos).filter((todo: Todo) => todo.completed).length);
    }
  };
