  const getById = (id: number) => todos[findIndex(id)];

  function addTodo(text: string): number {
    const todo: Todo = { id: nextId++, text, completed: false };
    todos.push(todo);
    return todo.id;
  }

  function getTodo(id: number): Todo | undefined {
    return getById(id);
  }

  function toggleTodo(id: number): void {
    const todo = getById(id);
    if (todo) {
      todo.completed = !todo.completed;
    }
  }

  function deleteTodo(id: number): void {
    const idx = findIndex(id);
    if (idx !== -1) {
      // Remove without reusing ids
      todos.splice(idx, 1);
    }
  }

  function listTodos(): Todo[] {
    return [...todos];
  }

  function listCompleted(): Todo[] {
    return todos.filter(t => t.completed);
  }

  function listPending(): Todo[] {
    return todos.filter(t => !t.completed);
  }

  function clearCompleted(): void {
    // Remove only completed items, keep order and preserve ids
    const pending = [];
    for (const todo of todos) {
      if (!todo.completed) pending.push(todo);
    }
    todos.length = 0;
    for (const t of pending) todos.push(t);
  }

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted,
