// Interface definitions
export interface Todo {
  id: number;
  text: string;
  completed: boolean;
}

export interface TodoApp {
  addTodo(text: string): Todo;
  getTodo(id: number): Todo | undefined;
  toggleTodo(id: number): void;
  deleteTodo(id: number): boolean;
  listTodos(): Todo[];
  listCompleted(): Todo[];
  listPending(): Todo[];
  clearCompleted(): void;
}

// Implementation factory
export function createTodoApp(): TodoApp {
  const store = new Map<number, Todo>();
  let nextId = 1;

  /** Auto‑incrementing unique IDs are never reused */
  const allocateId = (): number => {
    return nextId++;
  };

  const addTodo = (text: string): Todo => {
    const id = allocateId();
    const todo: Todo = { id, text, completed: false };
    store.set(id, todo);
    return todo;
  };

  const getTodo = (id: number): Todo | undefined => {
    return store.get(id);
  };

  const toggleTodo = (id: number): void => {
    const todo = getTodo(id);
    if (todo) {
      todo.completed = !todo.completed;
    }
  };

  const deleteTodo = (id: number): boolean => {
    // Returns true only if a todo was removed
    return store.delete(id);
  }

  const listTodos = (): Todo[] => {
    return Array.from(store.values());
  };

  const listCompleted = (): Todo[] => {
    return Array.from(store.values()).filter(todo => todo.completed);
  };

  const listPending = (): Todo[] => {
    return Array.from(store.values()).filter(todo => !todo.completed);
  };

  const clearCompleted = (): void => {
    // Remove only those with completed === true
    for (const [id, todo] of store.entries()) {
      if (todo.completed) {
        store.delete(id);
      }
    }
  };

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted,
  };
}
