export function createCalculator(): Calculator {
  let currentValue = 0;
  let memoryValue = 0;

  function updateCurrent(value: number): void {
    currentValue = value;
  }

  function getResult(): number {
    return currentValue;
  }

  function clearMemory(): void {
    memoryValue = 0;
  }

  function memoryAddToValue(): void {
    currentValue += memoryValue;
  }

  const calculator: Calculator = {
    add(n: number): Calculator {
      updateCurrent(currentValue + n);
      return this;
    },
    subtract(n: number): Calculator {
      updateCurrent(currentValue - n);
      return this;
    },
    multiply(n: number): Calculator {
      updateCurrent(currentValue * n);
      return this;
    },
    divide(n: number): Calculator {
      if (n !== 0) updateCurrent(currentValue / n);
      else throw new Error('Division by zero');
      return this;
    },
    clear(): Calculator {
      currentValue = 0;
      return this;
    },
    result(): number {
      return getResult();
    },
    memoryStore(): Calculator {
      memoryValue = currentValue;
      return this;
    },
    memoryRecall(): number {
      if (memoryValue === undefined) throw new Error('No value stored in memory');
      updateCurrent(memoryValue);
      return getResult();
    },
    memoryClear(): Calculator {
      clearMemory();
      return this;
    },
    memoryAdd(): Calculator {
      memoryAddToValue();
      return this;
    }
  };

  return calculator;
}

