  add(n: number): Calculator;
  /** Subtract a number from the current value. */
  subtract(n: number): Calculator;
  /** Multiply the current value by a number. */
  multiply(n: number): Calculator;
  /** Divide the current value by a number. */
  divide(n: number): Calculator;
  /** Reset the current value to 0. */
  clear(): Calculator;
  /** Return the current value. */
  result(): number;
  /** Copy the current value into memory. */
  memoryStore(): Calculator;
  /** Add the current value to the memory. */
  memoryAdd(): Calculator;
  /** Reset the memory to 0. */
  memoryClear(): Calculator;
  /** Return the value stored in memory (does not affect current value). */
  memoryRecall(): number;
}

