/**
 * A tiny in‑memory todo store.
 *
 * @module
 */

export interface Todo {
  /** Unique identifier, never reused after a todo is deleted. */
  id: number;
  /** The task description. */
  text: string;
  /** Whether the todo has been completed. */
  completed: boolean;
}

/**
 * Factory that creates a fresh todo store.
 *
 * @returns An object with todo manipulation helpers.
 */
export function createTodoApp() {
  // --- internal state -------------------------------------------------------
  /** All current todos in the order they were added. */
  const todos: Todo[] = [];
  /** Next auto‑incrementing id to assign. */
  let nextId = 1;

  // --- helpers ---------------------------------------------------------------
  const findIndex = (id: number): number => todos.findIndex((t) => t.id === id);

  // --- public API ------------------------------------------------------------
  /**
   * Add a new todo with the provided text.
   *
   * @param text The todo text.
   * @returns The newly created todo.
   */
  function addTodo(text: string): Todo {
    const todo: Todo = { id: nextId++, text, completed: false };
    todos.push(todo);
    return todo;
  }

  /**
   * Retrieve a todo by id.
   *
   * @param id The id of the todo.
   * @returns The matching todo or `undefined` if not found.
   */
  function getTodo(id: number): Todo | undefined {
    return todos.find((t) => t.id === id);
  }

  /**
   * Toggle the completed status of a todo.
   *
   * @param id The id of the todo.
   * @returns The updated todo, or `undefined` if not found.
   */
  function toggleTodo(id: number): Todo | undefined {
    const idx = findIndex(id);
    if (idx === -1) return undefined;
    todos[idx] = { ...todos[idx], completed: !todos[idx].completed };
    return todos[idx];
  }

  /**
   * Delete a todo from the store.
   *
   * @param id The id of the todo.
   * @returns `true` if a todo was removed; otherwise `false`.
   */
  function deleteTodo(id: number): boolean {
    const idx = findIndex(id);
    if (idx === -1) return false;
    todos.splice(idx, 1);
    return true;
  }

  /**
   * List all todos.
   *
   * @returns A shallow copy of the todo array.
   */
  function listTodos(): Todo[] {
    return [...todos];
  }

  /**
   * List only completed todos.
   *
   * @returns An array of completed todos.
   */
  function listCompleted(): Todo[] {
    return todos.filter((t) => t.completed);
  }

  /**
   * List only pending (not completed) todos.
   *
   * @returns An array of pending todos.
   */
  function listPending(): Todo[] {
    return todos.filter((t) => !t.completed);
  }

  /**
   * Remove all completed todos from the store.
   *
   * @returns The number of todos that were removed.
   */
  function clearCompleted(): number {
    const before = todos.length;
    // Re‑assign a new array without completed items.
    // eslint-disable-next-line prefer-const
    let remaining = todos.filter((t) => !t.completed);
    // Mutate the original `todos` array to keep the reference stable.
    while (todos.length) todos.pop();
    todos.push(...remaining);
    return before - todos.length;
  }

  // ---------------------------------------------------------------------------
  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted,
  } as const;
}
