/**
 * Simple calculator supporting chaining and a separate memory store.
 *
 * @module calculator
 */
export interface Calculator {
  /** Add a value to the current calculator value. */
  add(value: number): Calculator;
  /** Subtract a value from the current calculator value. */
  subtract(value: number): Calculator;
  /** Multiply the current calculator value by a factor. */
  multiply(value: number): Calculator;
  /**
   * Divide the current calculator value by a divisor.
   *
   * @throws {Error} If divisor is zero.
   */
  divide(value: number): Calculator;
  /** Reset the current calculator value to zero. */
  clear(): Calculator;
  /** Get the current value of the calculator. */
  result(): number;
  /** Store the current value in memory. */
  memoryStore(): Calculator;
  /** Add the current value to the stored memory value. */
  memoryAdd(): Calculator;
  /** Clear the memory value back to zero. */
  memoryClear(): Calculator;
  /** Retrieve the value stored in memory without modifying the calculator state. */
  memoryRecall(): number;
}

/**
 * Creates a new calculator instance.
 *
 * @returns {Calculator} A calculator instance with a pristine state.
 */
export function createCalculator(): Calculator {
  let current = 0;
  let memory = 0;

  const calculator: Calculator = {
    add(value) {
      current += value;
      return calculator;
    },
    subtract(value) {
      current -= value;
      return calculator;
    },
    multiply(value) {
      current *= value;
      return calculator;
    },
    divide(value) {
      if (value === 0) {
        throw new Error("Division by zero");
      }
      current /= value;
      return calculator;
    },
    clear() {
      current = 0;
      return calculator;
    },
    result() {
      return current;
    },
    memoryStore() {
      memory = current;
      return calculator;
    },
    memoryAdd() {
      memory += current;
      return calculator;
    },
    memoryClear() {
      memory = 0;
      return calculator;
    },
    memoryRecall() {
      return memory;
    },
  };

  return calculator;
}
