/**
 * @file calculator.ts
 * @description Simple calculator harness that supports chaining arithmetic operations
 *   and a lightweight memory facility.
 */

export function createCalculator(): Calculator {
  // Internal state
  let value = 0;
  let memory = 0;

  /**
   * The calculator object with all chainable methods.
   */
  const calculator: Calculator = {
    /**
     * Add a number to the current value.
     * @param n - Number to add.
     * @returns The calculator instance for chaining.
     */
    add(n: number): Calculator {
      value += n;
      return this;
    },

    /**
     * Subtract a number from the current value.
     * @param n - Number to subtract.
     * @returns The calculator instance for chaining.
     */
    subtract(n: number): Calculator {
      value -= n;
      return this;
    },

    /**
     * Multiply the current value by a number.
     * @param n - Number to multiply by.
     * @returns The calculator instance for chaining.
     */
    multiply(n: number): Calculator {
      value *= n;
      return this;
    },

    /**
     * Divide the current value by a number.
     * @param n - Number to divide by; must not be 0.
     * @returns The calculator instance for chaining.
     * @throws Will throw an error if division by zero is attempted.
     */
    divide(n: number): Calculator {
      if (n === 0) {
        throw new Error('Division by zero');
      }
      value /= n;
      return this;
    },

    /**
     * Reset the current value to 0.
     * @returns The calculator instance for chaining.
     */
    clear(): Calculator {
      value = 0;
      return this;
    },

    /**
     * Return the current calculated result.
     * @returns The numeric result.
     */
    result(): number {
      return value;
    },

    /**
     * Store the current value in memory.
     * @returns The calculator instance for chaining.
     */
    memoryStore(): Calculator {
      memory = value;
      return this;
    },

    /**
     * Recall the value stored in memory.
     * @returns The numeric memory value.
     */
    memoryRecall(): number {
      return memory;
    },

    /**
     * Clear the memory value (sets it to 0).
     * @returns The calculator instance for chaining.
     */
    memoryClear(): Calculator {
      memory = 0;
      return this;
    },

    /**
     * Add the current value to the memory (memory += value).
     * @returns The calculator instance for chaining.
     */
    memoryAdd(): Calculator {
      memory += value;
      return this;
    }
  };

  // Return the calculator object to the caller
  return calculator;
}

/**
 * @interface Calculator
 * @description The contract for the calculator returned by `createCalculator`.
 */
type Calculator = {
  add(n: number): Calculator;
  subtract(n: number): Calculator;
  multiply(n: number): Calculator;
  divide(n: number): Calculator;
  clear(): Calculator;
  result(): number;
  memoryStore(): Calculator;
  memoryRecall(): number;
  memoryClear(): Calculator;
  memoryAdd(): Calculator;
};
