    if (todo) {
      todo.completed = !todo.completed;
    }
    return todo;
  };

  /** Deletes a todo by its ID. */
  const deleteTodo = (id: number): Todo | undefined => {
    const index = todos.findIndex((t) => t.id === id);
    if (index !== -1) {
      return todos.splice(index, 1)[0];
    }
    return undefined;
  };

