/**
 * A lightweight todo‐application factory.
 *
 * The factory returns a `TodoApp` object that manages todos in memory
 * with auto‑incrementing, non‑reused identifiers.
 */
export function createTodoApp(): TodoApp {
  /** All known todos (including deleted ones); removed only when explicitly cleared. */
  const todos: Todo[] = []

  /** Next ID to assign. Never decremented; guarantees unique IDs. */
  let nextId = 1

  return {
    /**
     * Add a new todo.
     * @param text - The todo text.
     * @returns The added todo.
     */
    addTodo(text: string): Todo {
      const todo: Todo = { id: nextId++, text, completed: false }
      todos.push(todo)
      return todo
    },

    /**
     * Retrieve a todo by ID.
     * @param id - The ID of the todo.
     * @returns The todo, or `undefined` if not found.
     */
    getTodo(id: number): Todo | undefined {
      return todos.find((t) => t.id === id)
    },

    /**
     * Toggle the completed status of a todo.
     * @param id - The ID of the todo to toggle.
     */
    toggleTodo(id: number): void {
      const todo = todos.find((t) => t.id === id)
      if (todo) todo.completed = !todo.completed
    },

    /**
     * Delete a todo.
     * @param id - The ID of the todo to delete.
     * @returns `true` if removed, otherwise `false`.
     */
    deleteTodo(id: number): boolean {
      const idx = todos.findIndex((t) => t.id === id)
      if (idx < 0) return false
      todos.splice(idx, 1)
      return true
    },

    /**
     * Return all todos.
     * @returns A copy of the todo list.
     */
    listTodos(): Todo[] {
      return [...todos]
    },

    /**
     * Return only completed todos.
     * @returns A copy of completed todos.
     */
    listCompleted(): Todo[] {
      return todos.filter((t) => t.completed)
    },

    /**
     * Return only pending (incomplete) todos.
     * @returns A copy of pending todos.
     */
    listPending(): Todo[] {
      return todos.filter((t) => !t.completed)
    },

    /**
     * Remove all completed todos.
     */
    clearCompleted(): void {
      for (let i = todos.length - 1; i >= 0; i--) {
        if (todos[i].completed) {
          todos.splice(i, 1)
        }
      }
    },
  }
}

