     * @param text The text content of the todo.
     */
    addTodo(text: string): void {
      todos.push({ id: nextId, text, completed: false });
      nextId++;
    },

    /**
     * Retrieves a todo item by its ID.
     * @param id The unique ID of the todo.
     * @returns The todo object or `undefined` if not found.
     */
    getTodo(id: number): { id: number; text: string; completed: boolean } | undefined {
      return todos.find(todo => todo.id === id);
    },

    /**
     * Toggles the completed status of a todo item.
     * @param id The unique ID of the todo.
     */
    toggleTodo(id: number): void {
      const todo = todos.find(todo => todo.id === id);
      if (todo) {
        todo.completed = !todo.completed;
      }
    },

    /**
     * Deletes a todo item by its ID.
     * @param id The unique ID of the todo.
     */
    deleteTodo(id: number): void {
      todos = todos.filter(todo => todo.id !== id);
    },

    /**
     * Returns a copy of all todo items.
     * @returns An array of all todo items.
     */
    listTodos(): { id: number; text: string; completed: boolean }[] {
      return [...todos];
    },

    /**
     * Returns a copy of all completed todo items.
     * @returns An array of completed todo items.
     */
    listCompleted(): { id: number; text: string; completed: boolean }[] {
      return todos.filter(todo => todo.completed);
    },

    /**
     * Returns a copy of all pending (not completed) todo items.
     * @returns An array of pending todo items.
     */
    listPending(): { id: number; text: string; completed: boolean }[] {
      return todos.filter(todo => !todo.completed);
    },

    /**
     * Removes all completed todo items from the list.
     */
    clearCompleted(): void {
      todos = todos.filter(todo => !todo.completed);
    },
  };
}
