   * @param newValue - The new value to set.
   * @returns The calculator instance for chaining.
   */
  function setValue(newValue: number): typeof import("createCalculator")["createCalculator"];
  function setValue(val: number): typeof import("createCalculator")["createCalculator"] {
    value = val;
    return calculator;
  }

  /**
   * The calculator object with all functionalities.
   * Each method manipulates the internal state and returns the calculator instance
   * for method chaining.
   */
  const calculator: {
    add: (num: number) => typeof import("createCalculator")["createCalculator"];
    subtract: (num: number) => typeof import("createCalculator")["createCalculator"];
    multiply: (num: number) => typeof import("createCalculator")["createCalculator"];
    divide: (num: number) => typeof import("createCalculator")["createCalculator"];
    result: () => number;
    clear: () => typeof import("createCalculator")["createCalculator"];
    memoryStore: () => typeof import("createCalculator")["createCalculator"];
    memoryAdd: () => typeof import("createCalculator")["createCalculator"];
    memoryClear: () => typeof import("createCalculator")["createCalculator"];
    memoryRecall: () => number;
  } = {
    /**
     * Adds a number to the current value.
     */
    add(num: number) {
      setValue(value + num);
      return calculator;
    },

    /**
     * Subtracts a number from the current value.
     */
    subtract(num: number) {
      setValue(value - num);
      return calculator;
    },

    /**
     * Multiplies the current value by a number.
     */
    multiply(num: number) {
      setValue(value * num);
      return calculator;
    },

    /**
     * Divides the current value by a number. If division by zero is attempted,
     * the value remains unchanged.
     */
    divide(num: number) {
      if (num === 0) return calculator;
      setValue(value / num);
      return calculator;
    },

    /**
     * Returns the current value.
     */
    result() {
      return value;
    },

    /**
     * Resets the current value to 0.
     */
    clear() {
      setValue(0);
      return calculator;
    },

    /**
     * Copies the current value into memory.
     */
    memoryStore() {
      memory = value;
      return calculator;
