function createTodoApp() {
  const todos = [];
  let id = 1;

  const addTodo = (text: string): Todo => {
    const newTodo = {
      id,
      text,
      completed: false
    };
    todos.push(newTodo);
    id++;
    return newTodo;
  };

  const getTodo = (id: number): Todo | null => {
    for (const todo of todos) {
      if (todo.id === id) {
        return todo;
      }
    }
    return null;
  };

  const toggleTodo = (id: number): void => {
    const todo = getTodo(id);
    if (todo) {
      todo.completed = !todo.completed;
    }
  };

  const deleteTodo = (id: number): void => {
    const index = todos.findIndex(t => t.id === id);
    if (index !== -1) {
      todos.splice(index, 1);
    }
  };

  const listTodos = (): Todo[] => {
    return todos.sort((a, b) => a.id - b);
  };

  const listCompleted = (): Todo[] => {
    return todos.filter(t => t.completed);
  };

  const listPending = (): Todo[] => {
    return todos.filter(t => !t.completed);
  };

  const clearCompleted = (): void => {
    todos = todos.filter(t => !t.completed);
  };

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted
  };
}

