let nextId = 1;
const todos: Record<number, Todo> = {};

export function createTodoApp(): TodoApp {
  let maxId = 0;

  const addTodo = (text: string): Todo => {
    const todo: Todo = { id: nextId++, text, completed: false };
    todos[todo.id] = todo;
    if (todo.id > maxId) {
      maxId = todo.id;
    }
    return todo;
  };

  const getTodo = (id: number): Todo | undefined => todos[id];

  const toggleTodo = (id: number): void => {
    const todo = todos[id];
    if (todo) {
      todo.completed = !todo.completed;
    }
  };

  const deleteTodo = (id: number): boolean => {
    if (todos[id]) {
      delete todos[id];
      return true;
    }
    return false;
  };

  const listTodos = (): Todo[] => Object.values(todos);

  const listCompleted = (): Todo[] => listTodos().filter(todo => todo.completed);

  const listPending = (): Todo[] => listTodos().filter(todo => !todo.completed);

  const clearCompleted = (): void => {
    listCompleted().forEach(todo => deleteTodo(todo.id));
  };

  return { addTodo, getTodo, toggleTodo, deleteTodo, listTodos, listCompleted, listPending, clearCompleted };
}

interface Todo {
  id: number
  text: string
  completed: boolean
}

interface TodoApp {
  addTodo(text: string): Todo
  getTodo(id: number): Todo | undefined
