import { v4 as uuidv4 } from 'uuid';

interface Todo {
  id: number;
  text: string;
  completed: boolean;
}

class TodoManager {
  private todos: Map<number, Todo>;
  private nextId: number;

  constructor() {
    this.todos = new Map();
    this.nextId = 1;
  }

  addTodo(text: string): number {
    const id = this.nextId++;
    const todo: Todo = { id, text, completed: false };
    this.todos.set(id, todo);
    return id;
  }

  getTodo(id: number): Todo | undefined {
    return this.todos.get(id);
  }

  toggleTodo(id: number): void {
    const todo = this.todos.get(id);
    if (todo) {
      todo.completed = !todo.completed;
    }
  }

  deleteTodo(id: number): void {
    this.todos.delete(id);
  }

  listTodos(): Todo[] {
    return Array.from(this.todos.values());
  }

  listCompleted(): Todo[] {
    return Array.from(this.todos.values()).filter(todo => todo.completed);
  }

  listPending(): Todo[] {
    return Array.from(this.todos.values()).filter(todo => !todo.completed);
  }

  clearCompleted(): void {
    const pendingTodos = this.listPending();
    this.todos.clear();
    pendingTodos.forEach(todo => this.todos.set(todo.id, todo));
  }
}

export function createTodoApp(): {
  addTodo: (text: string) => number;
  getTodo: (id: number) => Todo | undefined;
  toggleTodo: (id: number) => void;
  deleteTodo: (id: number) => void;
  listTodos: () => Todo[];
  listCompleted: () => Todo[];
  listPending: () => Todo[];
  clearCompleted: () => void;
} {
  const manager = new TodoManager();
  return {
    addTodo: manager.addTodo.bind(manager),
    getTodo: manager.getTodo.bind(manager),
    toggleTodo: manager.toggleTodo.bind(manager),
    deleteTodo: manager.deleteTodo.bind(manager),
    listTodos: manager.listTodos.bind(manager),
    listCompleted: manager.listCompleted.bind(manager),
    listPending: manager.listPending.bind(manager),
    clearCompleted: manager.clearCompleted.bind(manager),
  };
}
