import { Todo, TodoApp } from './todoAppInterfaces';

let nextId = 1;
const todos: Map<number, Todo> = new Map();

export function createTodoApp(): TodoApp {
  return {
    addTodo(text: string): Todo {
      const todo: Todo = { id: nextId++, text, completed: false };
      todos.set(todo.id, todo);
      return todo;
    },
    getTodo(id: number): Todo | undefined {
      return todos.get(id);
    },
    toggleTodo(id: number): void {
      const todo = todos.get(id);
      if (todo) {
        todo.completed = !todo.completed;
      }
    },
    deleteTodo(id: number): boolean {
      if (todos.delete(id)) {
        return true;
      }
      return false;
    },
    listTodos(): Todo[] {
      return Array.from(todos.values());
    },
    listCompleted(): Todo[] {
      return Array.from(todos.values()).filter(todo => todo.completed);
    },
    listPending(): Todo[] {
      return Array.from(todos.values()).filter(todo => !todo.completed);
    },
    clearCompleted(): void {
      const completedTodos = Array.from(todos.values()).filter(todo => todo.completed);
      for (const todo of completedTodos) {
        todos.delete(todo.id);
      }
    }
  };
}
