import { v4 as uuidv4 } from 'uuid';

const todoStore = {
    todos: [] as { id: string, text: string, completed: boolean }[],
    nextId: 0,
};

export const createTodoApp = () => {
    const addTodo = (text: string) => {
        todoStore.todos.push({
            id: uuidv4(),
            text,
            completed: false,
        });
    };

    const getTodo = (id: string) => {
        return todoStore.todos.find(todo => todo.id === id);
    };

    const toggleTodo = (id: string) => {
        const todo = getTodo(id);
        if (todo) {
            todo.completed = !todo.completed;
        }
    };

    const deleteTodo = (id: string) => {
        todoStore.todos = todoStore.todos.filter(todo => todo.id !== id);
    };

    const listTodos = () => {
        return todoStore.todos.slice();
    };

    const listCompleted = () => {
        return todoStore.todos.filter(todo => todo.completed).slice();
    };

    const listPending = () => {
        return todoStore.todos.filter(todo => !todo.completed).slice();
    };

    const clearCompleted = () => {
        todoStore.todos = todoStore.todos.filter(todo => !todo.completed);
    };

    return {
        addTodo,
        getTodo,
        toggleTodo,
        deleteTodo,
        listTodos,
        listCompleted,
        listPending,
        clearCompleted,
    };
};
